import sys

def main():
    input = sys.stdin.readline
    n = int(input().strip())
    s = input().strip()
    half = n // 2

    left = s[:half]
    right = s[half:]

    sum_left = 0
    sum_right = 0
    q_left = 0
    q_right = 0

    for ch in left:
        if ch == '?':
            q_left += 1
        else:
            sum_left += ord(ch) - ord('0')

    for ch in right:
        if ch == '?':
            q_right += 1
        else:
            sum_right += ord(ch) - ord('0')

    # Let diff be current left sum - right sum.
    # Extra question marks on one side can contribute at most 9 each pair-turn effect,
    # and Bicarp wins iff the final balance can be made exactly zero under optimal play.
    diff = sum_left - sum_right

    if diff == (q_right - q_left) * 9 // 2:
        print("Bicarp")
    else:
        print("Monocarp")

if __name__ == "__main__":
    main()
